solutionCode:
import { useState } from 'react';

const INITIAL_USERS = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com', role: 'Admin' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com', role: 'Editor' },
  { id: 3, name: 'Carol Lee', email: 'carol@example.com', role: 'Viewer' },
  { id: 4, name: 'David Kim', email: 'david@example.com', role: 'Editor' },
  { id: 5, name: 'Eva Brown', email: 'eva@example.com', role: 'Viewer' }
];

export default function FilterableDataTable() {
  const [users] = useState(INITIAL_USERS);
  const [filterText, setFilterText] = useState('');
  const [sortField, setSortField] = useState<'name' | 'role'>('name');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

  const handleSort = (field: 'name' | 'role') => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const normalizedFilter = filterText.toLowerCase();
  const filtered = users.filter((user) => {
    if (!normalizedFilter) return true;
    return (
      user.name.toLowerCase().includes(normalizedFilter) ||
      user.email.toLowerCase().includes(normalizedFilter)
    );
  });

  const sorted = [...filtered].sort((a, b) => {
    let comparison = 0;
    if (sortField === 'name') {
      comparison = a.name.localeCompare(b.name);
    } else {
      comparison = a.role.localeCompare(b.role);
    }
    return sortDirection === 'asc' ? comparison : -comparison;
  });

  const sortArrow = (field: 'name' | 'role') => {
    if (sortField !== field) return '';
    return sortDirection === 'asc' ? '↑' : '↓';
  };

  return (
    <div>
      <h2>User Directory</h2>
      <div>
        <label>
          Filter by name or email:{' '}
          <input
            type="text"
            value={filterText}
            onChange={(e) => setFilterText(e.target.value)}
            placeholder="Search users..."
          />
        </label>
      </div>
      <table>
        <thead>
          <tr>
            <th onClick={() => handleSort('name')}>
              Name {sortArrow('name')}
            </th>
            <th>Email</th>
            <th onClick={() => handleSort('role')}>
              Role {sortArrow('role')}
            </th>
          </tr>
        </thead>
        <tbody>
          {sorted.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.email}</td>
              <td>{user.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
